// Platform centres read from the site-plan gridlines (Figure 1):
//   P = (3200, 3000), A = (-700, 2700).
const PLATFORMS = { P: [3200, 3000], A: [-700, 2700] };

// Cable catalogue read from Figure 2 (capacity = max turbines carried).
const CABLES = [
  { name: 'C1', cap: 4, price: 100 },
  { name: 'C2', cap: 8, price: 160 },
  { name: 'C3', cap: 14, price: 245 },
];

const SCENARIOS = {
  S1: { platform: 'P', types: ['C1', 'C2', 'C3'], B: 6 },
  S2: { platform: 'P', types: ['C1', 'C2', 'C3'], B: 5 },
  S3: { platform: 'P', types: ['C2', 'C3'], B: 6 },
  S4: { platform: 'A', types: ['C1', 'C2', 'C3'], B: 6 },
  S5: { platform: 'A', types: ['C1', 'C2', 'C3'], B: 5 },
};

const MAX_TT_LEN = 1300;

function isqrt(x) { // exact for 0 <= x < 2^53
  let r = Math.floor(Math.sqrt(x));
  while (r * r > x) r--;
  while ((r + 1) * (r + 1) <= x) r++;
