// = floor((isqrt(4 d^2) + 1) / 2) exactly.
function roundedLength(p, q) {
  const dx = p[0] - q[0], dy = p[1] - q[1];
  return Math.floor((isqrt(4 * (dx * dx + dy * dy)) + 1) / 2);
}

function orient(a, b, c) {
  const v = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
  return v > 0 ? 1 : (v < 0 ? -1 : 0);
}
function onSegment(a, b, p) { // p collinear with a,b: inside closed bounding box?
  return Math.min(a[0], b[0]) <= p[0] && p[0] <= Math.max(a[0], b[0]) &&
