// Packet rule: two cables cross if they share any point other than an
// endpoint they have in common (touching / collinear overlap count).
function cablesCross(pts, a, b, c, d) {
  const shared = [];
  if (a === c || a === d) shared.push(a);
  if (b === c || b === d) shared.push(b);
  if (shared.length === 2) return true;          // identical segment
  if (shared.length === 1) {
    const x = shared[0];
    const y1 = (a === x) ? b : a, y2 = (c === x) ? d : c;
    const X = pts[x], Y1 = pts[y1], Y2 = pts[y2];
    if (orient(X, Y1, Y2) !== 0) return false;
    // collinear: overlap iff Y1 and Y2 lie on the same side of X
    return (Y1[0] - X[0]) * (Y2[0] - X[0]) + (Y1[1] - X[1]) * (Y2[1] - X[1]) > 0;
  }
  return closedSegmentsIntersect(pts[a], pts[b], pts[c], pts[d]);
