// Build an instance for a scenario: nodes 0..63 turbines, node 64 = platform.
function buildInstance(scnName) {
  const scn = SCENARIOS[scnName];
  const n = TURBINES.length, R = n;
  const pts = TURBINES.concat([PLATFORMS[scn.platform]]);
  const types = CABLES.filter(c => scn.types.includes(c.name));
  const Q = Math.max(...types.map(t => t.cap));
  const priceOf = new Array(Q + 1).fill(0), typeOf = new Array(Q + 1).fill(null);
  for (let q = 1; q <= Q; q++) { // cheapest available type with capacity >= q
    let best = null;
    for (const t of types) if (t.cap >= q && (best === null || t.price < best.price)) best = t;
    priceOf[q] = best.price; typeOf[q] = best.name;
  }
  const edges = [];               // {a,b,len}  (a<b; b may be R)
  const eid = new Int32Array((n + 1) * (n + 1)).fill(-1);
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const L = roundedLength(pts[i], pts[j]);
    if (L <= MAX_TT_LEN) edges.push({ a: i, b: j, len: L });
  }
  for (let i = 0; i < n; i++) edges.push({ a: i, b: R, len: roundedLength(pts[i], pts[R]) });
  edges.forEach((e, k) => { eid[e.a * (n + 1) + e.b] = k; eid[e.b * (n + 1) + e.a] = k; });
  const adj = Array.from({ length: n + 1 }, () => []);
  edges.forEach((e, k) => { adj[e.a].push(e.b); adj[e.b].push(e.a); });
  const cross = edges.map(() => []);
  for (let x = 0; x < edges.length; x++) for (let y = x + 1; y < edges.length; y++) {
    const e = edges[x], f = edges[y];
    if (cablesCross(pts, e.a, e.b, f.a, f.b)) { cross[x].push(y); cross[y].push(x); }
  }
  return { name: scnName, scn, n, R, pts, Q, priceOf, typeOf, edges, eid, adj, cross, B: scn.B };
