function label(inst, v) { return v === inst.R ? inst.scn.platform : 'T' + String(v + 1).padStart(2, '0'); }

// Evaluate a parent-array layout exactly (used for reporting).
function evaluate(inst, par) {
  const { n, R, Q } = inst;
  const load = new Array(n).fill(1);
  // loads via repeated parent walks (n small)
  for (let i = 0; i < n; i++) {
    let v = par[i], steps = 0;
    while (v !== R) { load[v]++; v = par[v]; if (++steps > n) throw new Error('cycle'); }
  }
  let cost = 0, feeders = 0, maxLoad = 0;
  const cables = [];
  for (let i = 0; i < n; i++) {
    const e = inst.eid[i * (n + 1) + par[i]];
    if (e < 0) throw new Error('non-candidate edge ' + label(inst, i) + '-' + label(inst, par[i]));
    const L = inst.edges[e].len, q = load[i];
    if (q > Q) throw new Error('overload');
    cost += L * inst.priceOf[q];
    if (par[i] === R) feeders++;
    maxLoad = Math.max(maxLoad, q);
    cables.push({ from: i, to: par[i], len: L, load: q, type: inst.typeOf[q], cost: L * inst.priceOf[q] });
  }
  return { cost, feeders, maxLoad, cables, load };
}

module.exports = { TURBINES, PLATFORMS, CABLES, SCENARIOS, MAX_TT_LEN, roundedLength, orient,
  cablesCross, buildInstance, label, evaluate };
