'use strict';
// Simulated annealing / local search over rooted non-crossing capacitated trees.
// Move = cut the cable u->par(u), re-root the detached subtree at one of its
// nodes k, and attach k to a new neighbour v outside the subtree.
const C = require('./common.js');

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class TreeState {
  constructor(inst, par, opts = {}) {
    this.inst = inst;
    const n = inst.n, N1 = n + 1;
    this.n = n; this.R = inst.R; this.N1 = N1;
    this.WL = opts.WL ?? 300000;   // penalty per unit of excess load per cable
    this.WF = opts.WF ?? 3000000;  // penalty per feeder above B
    this.B = inst.B; this.Q = inst.Q;
    // extended price table (loads above Q priced at largest type + penalty)
    this.price = new Float64Array(n + 2);
    this.pen = new Float64Array(n + 2);
    for (let q = 1; q <= n + 1; q++) {
      this.price[q] = inst.priceOf[Math.min(q, inst.Q)];
      this.pen[q] = q > inst.Q ? this.WL * (q - inst.Q) : 0;
    }
    this.lenM = new Float64Array(N1 * N1);
    for (let i = 0; i < N1; i++) for (let j = 0; j < N1; j++) this.lenM[i * N1 + j] = C.roundedLength(inst.pts[i], inst.pts[j]);
    this.eid = inst.eid;
    this.crossArr = inst.cross.map(l => Int32Array.from(l));
    this.adjArr = inst.adj.map(l => Int32Array.from(l));
    this.par = new Int32Array(N1); this.load = new Int32Array(N1);
    this.children = Array.from({ length: N1 }, () => []);
    this.used = new Uint8Array(inst.edges.length);
    this.mark = new Int32Array(N1); this.stamp = 1;
    this.pathBuf = new Int32Array(N1); this.oldLoadBuf = new Int32Array(N1);
    this.setPar(par);
  }
  ec(len, q) { return len * this.price[q] + this.pen[q]; }
  setPar(par) {
    const { n, R, N1 } = this;
    for (let i = 0; i < N1; i++) this.children[i].length = 0;
    this.used.fill(0);
    for (let i = 0; i < n; i++) { this.par[i] = par[i]; this.children[par[i]].push(i); }
    this.par[R] = -1;
    this.load.fill(0);
    for (let i = 0; i < n; i++) { let v = i, g = 0; while (v !== R) { this.load[v]++; v = this.par[v]; if (++g > n + 1) throw new Error('cycle'); } }
    this.nf = 0; this.cost = 0;
    for (let i = 0; i < n; i++) {
      const e = this.eid[i * N1 + par[i]];
      if (e < 0) throw new Error('non-candidate edge');
      this.used[e] = 1;
      if (par[i] === R) this.nf++;
      this.cost += this.ec(this.lenM[i * N1 + par[i]], this.load[i]);
    }
  }
  objective() { return this.cost + this.WF * Math.max(0, this.nf - this.B); }
  feasible() {
    if (this.nf > this.B) return false;
    for (let i = 0; i < this.n; i++) if (this.load[i] > this.Q) return false;
    return true;
  }
  trueCost() { // cost without penalties (valid only when feasible)
    let c = 0; const { n, N1 } = this;
    for (let i = 0; i < n; i++) c += this.lenM[i * N1 + this.par[i]] * this.price[this.load[i]];
    return c;
  }
  // Evaluate move (u: cut point, k: new subtree root inside subtree(u), v: new parent).
  // Returns delta objective or NaN if infeasible (hard constraints).
  evalMove(u, k, v) {
    const { R, N1, par, load, lenM } = this;
    const p0 = par[u];
    if (k === u && v === p0) return NaN;
    if (v !== R) { let w = v; while (w !== R) { if (w === u) return NaN; w = par[w]; } }
    const eNew = this.eid[k * N1 + v];
    if (eNew < 0) return NaN;
    const eOld = this.eid[u * N1 + p0];
    const cl = this.crossArr[eNew], used = this.used;
    for (let t = 0; t < cl.length; t++) { const f = cl[t]; if (used[f] && f !== eOld) return NaN; }
    const s = load[u];
    let delta = this.ec(lenM[k * N1 + v], s) - this.ec(lenM[u * N1 + p0], s);
    if (k !== u) {
      let w = k;
      while (w !== u) { const pw = par[w]; const L = lenM[w * N1 + pw]; delta += this.ec(L, s - load[w]) - this.ec(L, load[w]); w = pw; }
    }
    const st = ++this.stamp; const mark = this.mark;
    let w = p0; while (w !== R) { mark[w] = st; w = par[w]; }
    w = v;
    while (w !== R && mark[w] !== st) { const L = lenM[w * N1 + par[w]]; delta += this.ec(L, load[w] + s) - this.ec(L, load[w]); w = par[w]; }
    const meet = w;
    w = p0;
    while (w !== meet) { const L = lenM[w * N1 + par[w]]; delta += this.ec(L, load[w] - s) - this.ec(L, load[w]); w = par[w]; }
    const nfNew = this.nf + (v === R ? 1 : 0) - (p0 === R ? 1 : 0);
    delta += this.WF * (Math.max(0, nfNew - this.B) - Math.max(0, this.nf - this.B));
    return delta;
  }
  applyMove(u, k, v, delta) {
    const { R, N1, par, load, children } = this;
    const p0 = par[u], s = load[u];
    // loads outside subtree
    const st = ++this.stamp; const mark = this.mark;
    let w = p0; while (w !== R) { mark[w] = st; w = par[w]; }
    w = v; while (w !== R && mark[w] !== st) { load[w] += s; w = par[w]; }
    const meet = w;
    w = p0; while (w !== meet) { load[w] -= s; w = par[w]; }
    // detach
    const eOld = this.eid[u * N1 + p0], eNew = this.eid[k * N1 + v];
    this.used[eOld] = 0; this.used[eNew] = 1;
    removeFrom(children[p0], u);
    if (k !== u) {
      // path k = w0 -> w1 -> ... -> wm = u
      let m = 0; w = k;
      while (true) { this.pathBuf[m] = w; this.oldLoadBuf[m] = load[w]; if (w === u) break; w = par[w]; m++; }
      for (let t = 0; t < m; t++) {
        const a = this.pathBuf[t], b = this.pathBuf[t + 1];
        removeFrom(children[b], a); children[a].push(b); par[b] = a; load[b] = s - this.oldLoadBuf[t];
      }
    }
    par[k] = v; load[k] = s; children[v].push(k);
    this.nf += (v === R ? 1 : 0) - (p0 === R ? 1 : 0);
    // cost (without feeder penalty) update: recompute delta minus feeder part
    this.cost = 0; // recompute lazily below for exactness
    const n = this.n;
    for (let i = 0; i < n; i++) this.cost += this.ec(this.lenM[i * N1 + par[i]], load[i]);
  }
}
function removeFrom(arr, x) { const i = arr.indexOf(x); arr[i] = arr[arr.length - 1]; arr.pop(); }

// Initial tree: MST of turbines over candidate edges (Prim), one feeder from
// a turbine whose feeder cable crosses nothing.
function initialTree(inst, rnd) {
  const { n, R, edges, eid } = inst;
  const N1 = n + 1;
  const inT = new Uint8Array(n), best = new Float64Array(n).fill(Infinity), bp = new Int32Array(n).fill(-1);
  const par = new Int32Array(n).fill(-1);
  const start = Math.floor(rnd() * n);
  best[start] = 0;
  for (let it = 0; it < n; it++) {
    let u = -1; for (let i = 0; i < n; i++) if (!inT[i] && (u < 0 || best[i] < best[u])) u = i;
    if (best[u] === Infinity) throw new Error('candidate graph disconnected');
    inT[u] = 1; par[u] = bp[u];
    for (const v of inst.adj[u]) if (v !== R && !inT[v]) { const L = edges[eid[u * N1 + v]].len; if (L < best[v]) { best[v] = L; bp[v] = u; } }
  }
  // orient towards a root turbine r whose feeder does not cross MST edges
  const und = []; for (let i = 0; i < n; i++) if (par[i] >= 0) und.push([i, par[i]]);
  const order = [...Array(n).keys()].sort((a, b) => edges[eid[a * N1 + R]].len - edges[eid[b * N1 + R]].len);
  let r = -1;
  for (const cand of order) {
    const ef = eid[cand * N1 + R]; const cs = new Set(inst.cross[ef]);
    if (und.every(([a, b]) => !cs.has(eid[a * N1 + b]))) { r = cand; break; }
  }
  if (r < 0) throw new Error('no crossing-free feeder');
  const nb = Array.from({ length: n }, () => []);
  for (const [a, b] of und) { nb[a].push(b); nb[b].push(a); }
  const out = new Array(n).fill(-1); out[r] = R;
  const stack = [r], seen = new Uint8Array(n); seen[r] = 1;
  while (stack.length) { const x = stack.pop(); for (const y of nb[x]) if (!seen[y]) { seen[y] = 1; out[y] = x; stack.push(y); } }
  return out;
}

// One SA run.  Returns best feasible parent array and its cost.
function anneal(inst, opts) {
  const rnd = mulberry32(opts.seed);
  const par0 = opts.startPar ? Array.from(opts.startPar) : initialTree(inst, rnd);
  const S = new TreeState(inst, par0, opts);
  const n = S.n, R = S.R, N1 = S.N1;
  const iters = opts.iters, T0 = opts.T0, T1 = opts.T1;
  let bestCost = Infinity, bestPar = null;
  if (S.feasible()) { bestCost = S.trueCost(); bestPar = Array.from(S.par.subarray(0, n)); }
  let obj = S.objective();
  const anc = new Int32Array(N1);
  const logRatio = Math.log(T1 / T0);
  for (let it = 0; it < iters; it++) {
    const T = T0 * Math.exp(logRatio * it / iters);
    const k = Math.floor(rnd() * n);
    // choose cut point u among ancestors of k (including k)
    let m = 0, w = k; while (w !== R) { anc[m++] = w; w = S.par[w]; }
    const u = (rnd() < 0.5) ? k : anc[Math.floor(rnd() * m)];
    const nbrs = S.adjArr[k];
    const v = nbrs[Math.floor(rnd() * nbrs.length)];
    const d = S.evalMove(u, k, v);
    if (d !== d) continue; // NaN
    if (d <= 0 || rnd() < Math.exp(-d / T)) {
      S.applyMove(u, k, v, d);
      obj = S.objective();
      if (obj < bestCost && S.feasible()) {
        const c = S.trueCost();
        if (c < bestCost) { bestCost = c; bestPar = Array.from(S.par.subarray(0, n)); }
      }
    }
  }
  return { bestCost, bestPar };
}

// Exhaustive first-improvement local search with the same move set.
function localSearch(inst, par, opts = {}) {
  const S = new TreeState(inst, par, opts);
  const n = S.n, R = S.R;
  let improved = true;
  while (improved) {
    improved = false;
    for (let k = 0; k < n && !improved; k++) {
      // ancestors of k
      const anc = []; let w = k; while (w !== R) { anc.push(w); w = S.par[w]; }
      for (const u of anc) {
        for (const v of S.adjArr[k]) {
          const d = S.evalMove(u, k, v);
          if (d === d && d < -1e-9) { S.applyMove(u, k, v, d); improved = true; break; }
        }
        if (improved) break;
      }
    }
  }
  return { par: Array.from(S.par.subarray(0, n)), cost: S.trueCost(), feasible: S.feasible() };
}

module.exports = { mulberry32, TreeState, initialTree, anneal, localSearch };
