'use strict';
// Lagrangian lower bound for the ARRAY-11 cable layout problem.
//
// Relaxation: every feasible layout is a set of <= B trees ("feeders") hanging
// off the platform, with total size n, in which every turbine occurs exactly
// once.  We relax "exactly once" (multipliers lam[k], free sign) and the
// pairwise non-crossing constraints x_e + x_f <= 1 (multipliers mu >= 0), and
// we allow non-elementary "pseudo-trees" (a turbine may re-occur), keeping
//   * exact load-dependent cable prices (DP indexed by subtree size q <= Q),
//   * distinct children at every node, a node's parent may not be its child,
//   * the 1300 m turbine-turbine limit (only candidate arcs are used),
//   * <= B feeders whose sizes sum to exactly n.
// For ANY lam and mu >= 0 the DP optimum + sum(lam) - sum(mu) is a valid lower
// bound on the optimal cost.  Subgradient optimisation searches for good
// multipliers.  The final bound is re-evaluated from the stored multipliers.
const C = require('./common.js');

function makeLB(inst) {
  const n = inst.n, R = inst.R, N1 = n + 1, Q = inst.Q;
  const nbT = Array.from({ length: n }, () => []);   // turbine neighbours
  for (const e of inst.edges) if (e.b !== R) { nbT[e.a].push(e.b); nbT[e.b].push(e.a); }
  const lenM = new Float64Array(N1 * N1);
  for (let i = 0; i < N1; i++) for (let j = 0; j < N1; j++) lenM[i * N1 + j] = C.roundedLength(inst.pts[i], inst.pts[j]);
  // parent slots for node k: its turbine neighbours, then R  (slot index)
  const parents = nbT.map(l => l.concat([R]));
  const slotOf = new Map(); // key k*N1+p -> slot
  parents.forEach((l, k) => l.forEach((p, s) => slotOf.set(k * N1 + p, s)));
  // crossing pairs (undirected edge ids)
  const pairs = [];
  inst.cross.forEach((l, e) => { for (const f of l) if (f > e) pairs.push([e, f]); });
  return { inst, n, R, N1, Q, nbT, lenM, parents, slotOf, pairs };
}

// Evaluate the Lagrangian function.  Returns {lb, trees, cnt, edgeUse}.
// fixedOut (optional): Int32Array(n), -1 = free, else forced parent of k.
// forbid (optional): Set of directed arc keys k*N1+p that may not be used.
function evalLagrangian(L, lam, edgePen, wantTrees = true) {
  const { n, R, N1, Q, nbT, lenM, parents, inst } = L;
  const price = inst.priceOf, eid = inst.eid;
  // G[k][slot][q]  q = 1..Q
  const G = parents.map(l => l.map(() => new Float64Array(Q + 1).fill(Infinity)));
  for (let k = 0; k < n; k++) for (let s = 0; s < parents[k].length; s++) G[k][s][1] = -lam[k];
  // a(j,q | parent k) = G(j, q, k) + c(j->k, q)
  const D = new Float64Array(Q + 1);
  for (let s = 1; s < Q; s++) {            // compute H(k, s, p) then G(k, s+1, p)
    for (let k = 0; k < n; k++) {
      const nb = nbT[k];
      for (let ps = 0; ps < parents[k].length; ps++) {
        const p = parents[k][ps];
        D.fill(Infinity, 0, s + 1); D[0] = 0;
        for (const j of nb) {
          if (j === p) continue;
          const sj = L.slotOf.get(j * N1 + k);
          const Gj = G[j][sj];
          const Ljk = lenM[j * N1 + k], pen = edgePen[eid[j * N1 + k]];
          for (let t = s; t >= 1; t--) {
            let best = D[t];
            for (let q = 1; q <= t; q++) {
              const base = D[t - q]; if (base === Infinity) continue;
              const g = Gj[q]; if (g === Infinity) continue;
              const v = base + g + Ljk * price[q] + pen;
              if (v < best) best = v;
            }
            D[t] = best;
          }
        }
        if (D[s] < Infinity) G[k][ps][s + 1] = -lam[k] + D[s];
      }
    }
  }
  // feeder values F(q)
  const F = new Float64Array(Q + 1).fill(Infinity), Fk = new Int32Array(Q + 1).fill(-1);
  for (let k = 0; k < n; k++) {
    const sR = parents[k].length - 1, pen = edgePen[eid[k * N1 + R]], Lk = lenM[k * N1 + R];
    for (let q = 1; q <= Q; q++) {
      const v = G[k][sR][q] + Lk * price[q] + pen;
      if (v < F[q]) { F[q] = v; Fk[q] = k; }
    }
  }
  // master: <= B feeders, sizes sum to n
  const B = inst.B;
  const M = Array.from({ length: B + 1 }, () => new Float64Array(n + 1).fill(Infinity));
  const Mq = Array.from({ length: B + 1 }, () => new Int32Array(n + 1).fill(-1));
  M[0][0] = 0;
  for (let b = 1; b <= B; b++) for (let t = 1; t <= n; t++) {
    let best = Infinity, bq = -1;
    for (let q = 1; q <= Math.min(Q, t); q++) { const v = M[b - 1][t - q] + F[q]; if (v < best) { best = v; bq = q; } }
    M[b][t] = best; Mq[b][t] = bq;
  }
  let bb = -1, val = Infinity;
  for (let b = 1; b <= B; b++) if (M[b][n] < val) { val = M[b][n]; bb = b; }
  let lamSum = 0; for (let k = 0; k < n; k++) lamSum += lam[k];
  const res = { value: val + lamSum, F, Fk };
  if (!wantTrees) return res;
  // backtrack chosen pseudo-trees
  const cnt = new Int32Array(n), edgeUse = new Map();
  const arcs = [];
  function expand(k, p, q) {
    cnt[k]++;
    if (q === 1) return;
    // recompute knapsack for (k, p, s=q-1) with choice tracking
    const s = q - 1, nb = nbT[k].filter(j => j !== p);
    const Dt = nb.map(() => new Float64Array(s + 1).fill(Infinity));
    const ch = nb.map(() => new Int32Array(s + 1).fill(0));
    let prev = new Float64Array(s + 1).fill(Infinity); prev[0] = 0;
    nb.forEach((j, idx) => {
      const sj = L.slotOf.get(j * N1 + k), Gj = G[j][sj], Ljk = lenM[j * N1 + k], pen = edgePen[eid[j * N1 + k]];
      const cur = Dt[idx];
      for (let t = 0; t <= s; t++) {
        let best = prev[t], bc = 0;
        for (let qq = 1; qq <= t; qq++) {
          if (prev[t - qq] === Infinity || Gj[qq] === Infinity) continue;
          const v = prev[t - qq] + Gj[qq] + Ljk * price[qq] + pen;
          if (v < best - 1e-9) { best = v; bc = qq; }
        }
        cur[t] = best; ch[idx][t] = bc;
      }
      prev = cur;
    });
    let t = s;
    for (let idx = nb.length - 1; idx >= 0; idx--) {
      const qq = ch[idx][t];
      if (qq > 0) { const j = nb[idx]; arcs.push([j, k, qq]); const e = eid[j * N1 + k]; edgeUse.set(e, (edgeUse.get(e) || 0) + 1); expand(j, k, qq); t -= qq; }
    }
  }
  let t = n, b = bb; const roots = [];
  while (b > 0) { const q = Mq[b][t]; const k = Fk[q]; roots.push([k, q]); arcs.push([k, R, q]); const e = eid[k * N1 + R]; edgeUse.set(e, (edgeUse.get(e) || 0) + 1); expand(k, R, q); t -= q; b--; }
  res.cnt = cnt; res.edgeUse = edgeUse; res.roots = roots; res.arcs = arcs;
  return res;
}

// Subgradient optimisation of (lam, mu).  UB is used in Polyak steps.
function optimiseBound(L, UB, opts = {}) {
  const { n, inst, pairs } = L;
  const iters = opts.iters ?? 3000;
  const useCross = opts.useCross ?? true;
  const nE = inst.edges.length;
  const lam = new Float64Array(n);
  // start: lam_k = average cost per turbine
  for (let k = 0; k < n; k++) lam[k] = opts.lam0 ? opts.lam0[k] : UB / n;
  const mu = new Float64Array(pairs.length);
  if (opts.mu0) mu.set(opts.mu0);
  const edgePen = new Float64Array(nE);
  let best = -Infinity, bestLam = Float64Array.from(lam), bestMu = Float64Array.from(mu);
  let theta = opts.theta0 ?? 1.0, noImp = 0;
  for (let it = 0; it < iters; it++) {
    edgePen.fill(0);
    let muSum = 0;
    if (useCross) for (let p = 0; p < pairs.length; p++) { if (mu[p] > 0) { edgePen[pairs[p][0]] += mu[p]; edgePen[pairs[p][1]] += mu[p]; muSum += mu[p]; } }
    const r = evalLagrangian(L, lam, edgePen, true);
    const lb = r.value - muSum;
    if (lb > best + 1e-6) { best = lb; bestLam = Float64Array.from(lam); bestMu = Float64Array.from(mu); noImp = 0; }
    else if (++noImp >= (opts.patience ?? 40)) { theta *= 0.7; noImp = 0; }
    // subgradients
    const g = new Float64Array(n); let norm = 0;
    for (let k = 0; k < n; k++) { g[k] = 1 - r.cnt[k]; norm += g[k] * g[k]; }
    const gm = new Float64Array(pairs.length);
    if (useCross) for (let p = 0; p < pairs.length; p++) {
      const x = (r.edgeUse.get(pairs[p][0]) || 0) + (r.edgeUse.get(pairs[p][1]) || 0) - 1;
      gm[p] = (mu[p] > 0 || x > 0) ? x : 0; norm += gm[p] * gm[p];
    }
    if (norm === 0) { best = Math.max(best, lb); break; } // optimal for the relaxation
    const step = theta * (UB - lb) / norm;
    for (let k = 0; k < n; k++) lam[k] += step * g[k];
    if (useCross) for (let p = 0; p < pairs.length; p++) mu[p] = Math.max(0, mu[p] + step * gm[p]);
    if (opts.verbose && it % (opts.verbose) === 0) console.error(`it ${it} lb ${lb.toFixed(1)} best ${best.toFixed(1)} theta ${theta.toFixed(4)}`);
    if (theta < 1e-5) break;
  }
  return { best, lam: bestLam, mu: bestMu };
}

// Recompute the bound exactly from stored multipliers (validity check).
function boundFromMultipliers(L, lam, mu) {
  const nE = L.inst.edges.length, edgePen = new Float64Array(nE);
  let muSum = 0;
  L.pairs.forEach(([e, f], p) => { if (mu[p] > 0) { edgePen[e] += mu[p]; edgePen[f] += mu[p]; muSum += mu[p]; } });
  const r = evalLagrangian(L, lam, edgePen, false);
  return r.value - muSum;
}

module.exports = { makeLB, evalLagrangian, optimiseBound, boundFromMultipliers };

if (require.main === module) {
  const scn = process.argv[2] || 'S1';
  const UB = +(process.argv[3] || 6e6);
  const iters = +(process.argv[4] || 2000);
  const useCross = process.argv[5] !== 'nocross';
  const inst = C.buildInstance(scn);
  const L = makeLB(inst);
  const t0 = Date.now();
  const r = optimiseBound(L, UB, { iters, useCross, verbose: 100 });
  console.log(scn, 'LB', r.best.toFixed(2), 'recomputed', boundFromMultipliers(L, r.lam, r.mu).toFixed(2), 'UB', UB, 'gap %', (100 * (UB - r.best) / UB).toFixed(3), 'time', Date.now() - t0, 'ms');
}
