    if (lb > best + 1e-6) { best = lb; bestLam = Float64Array.from(lam); bestMu = Float64Array.from(mu); bestCuts = cuts.map(c => ({ ...c })); noImp = 0; }
    else if (++noImp >= (opts.patience ?? 40)) { theta *= 0.7; noImp = 0; }
    // --- separation of GSECs from repeated turbines within a feeder pseudo-tree
