'use strict';
// Fast Lagrangian pseudo-tree DP (used by the lower-bound program and the
// branch-and-bound).  See lowerbound.js for the description of the relaxation.
//
// Directed arcs: for every turbine k, its possible parents are its candidate
// turbine neighbours and the platform R.  arc id a <-> (k, parent p).
const C = require('./common.js');

function build(inst) {
  const n = inst.n, R = inst.R, N1 = n + 1, Q = inst.Q;
  const nbT = Array.from({ length: n }, () => []);
  for (const e of inst.edges) if (e.b !== R) { nbT[e.a].push(e.b); nbT[e.b].push(e.a); }
  for (const l of nbT) l.sort((a, b) => a - b);
  const arcTail = [], arcHead = [], arcLen = [], arcEdge = [];
  const arcOf = new Int32Array(N1 * N1).fill(-1);
  for (let k = 0; k < n; k++) {
    for (const p of nbT[k].concat([R])) {
      const a = arcTail.length;
      arcTail.push(k); arcHead.push(p);
      arcLen.push(C.roundedLength(inst.pts[k], inst.pts[p]));
      arcEdge.push(inst.eid[k * N1 + p]);
      arcOf[k * N1 + p] = a;
    }
  }
  const nA = arcTail.length;
  // children arcs of arc a=(k->p): arcs (j->k), j in nbT[k], j != p
  const childArcs = [];
  for (let a = 0; a < nA; a++) {
    const k = arcTail[a], p = arcHead[a];
    childArcs.push(Int32Array.from(nbT[k].filter(j => j !== p).map(j => arcOf[j * N1 + k])));
  }
  const rootArcs = Int32Array.from([...Array(n).keys()].map(k => arcOf[k * N1 + R]));
  // arcs of each undirected edge
  const edgeArcs = inst.edges.map(() => []);
  for (let a = 0; a < nA; a++) edgeArcs[arcEdge[a]].push(a);
  return { inst, n, R, N1, Q, B: inst.B, nbT, nA, arcTail: Int32Array.from(arcTail), arcHead: Int32Array.from(arcHead),
    arcLen: Float64Array.from(arcLen), arcEdge: Int32Array.from(arcEdge), arcOf, childArcs, rootArcs, edgeArcs,
    price: Float64Array.from(inst.priceOf),
    G: new Float64Array(nA * (Q + 1)), A: new Float64Array(nA * (Q + 1)), D: new Float64Array(Q + 1) };
}

// lam: Float64Array(n); arcPen: Float64Array(nA) extra cost per arc use (load independent)
// allowed: Uint8Array(nA) (1 = arc usable)
// Returns value (without subtracting penalty constants) and optional solution.
function evaluate(S, lam, arcPen, allowed, want) {
  const { n, Q, nA, arcTail, arcLen, childArcs, rootArcs, price, G, A, D, B } = S;
  const W = Q + 1;
  G.fill(Infinity); A.fill(Infinity);
  for (let a = 0; a < nA; a++) {
    if (!allowed[a]) continue;
    const g = -lam[arcTail[a]];
    G[a * W + 1] = g;
    A[a * W + 1] = g + arcLen[a] * price[1] + arcPen[a];
  }
  for (let s = 1; s < Q; s++) {
    for (let a = 0; a < nA; a++) {
      if (!allowed[a]) continue;
      const ch = childArcs[a];
      D[0] = 0; for (let t = 1; t <= s; t++) D[t] = Infinity;
      for (let ci = 0; ci < ch.length; ci++) {
        const c = ch[ci]; if (!allowed[c]) continue;
        const base = c * W;
