      for (let q = 1; q <= Q && t + q <= n; q++) { const v = base + A[a * W + q]; if (v < NM[b + 1][t + q]) NM[b + 1][t + q] = v; }
    }
    hist.push({ a, Mprev: M }); M = NM;
  });
  // free feeders (unbounded multiplicity) -- process b increasing
  const Mf = M.map(r => Float64Array.from(r));
  const fq = Array.from({ length: B + 1 }, () => new Int32Array(n + 1).fill(-1));
  for (let b = 1; b <= B; b++) for (let t = 1; t <= n; t++) {
    for (let q = 1; q <= Math.min(Q, t); q++) { const base = Mf[b - 1][t - q]; if (base === Infinity) continue; const v = base + Ffree[q]; if (v < Mf[b][t]) { Mf[b][t] = v; fq[b][t] = q; } }
  }
  const backtrack = (b, t) => {
    const picks = [];
    while (fq[b][t] >= 0) { const q = fq[b][t]; picks.push([null, q]); b--; t -= q; }
    // remaining must equal forced-only table M at (b,t)
    for (let h = hist.length - 1; h >= 0; h--) {
      const { a, Mprev } = hist[h];
      let found = false;
      for (let q = 1; q <= Q && q <= t; q++) {
        const v = Mprev[b - 1] ? Mprev[b - 1][t - q] + A[a * W + q] : Infinity;
        if (b >= 1 && Math.abs(v - (h === hist.length - 1 ? M[b][t] : hist[h + 1].Mprev[b][t])) < 1e-6 * Math.max(1, Math.abs(v))) { picks.push([a, q]); b--; t -= q; found = true; break; }
      }
      if (!found) throw new Error('master backtrack failed');
    }
    return picks;
  };
  return { M: Mf, Mforced: M, backtrack };
}

// Outside values: useVal[a*W+q] = best relaxed value of solutions using arc a with load q.
function arcUseValues(S, lam, ok, forcedArc, ev) {
  const { n, Q, W, nA, arcTail, arcLen, childArcs, rootArcs, price, A, B } = S;
  const isMand = (c) => forcedArc[arcTail[c]] === c;
  let lamSum = 0; for (let k = 0; k < n; k++) lamSum += lam[k];
  const Out = new Float64Array(nA * W).fill(Infinity);
  const forcedRoots = ev.forcedRoots, Ffree = ev.Ffree;
  // root arcs
  const full = masterTables(S, forcedRoots, Ffree, -1).M;
  for (let i = 0; i < rootArcs.length; i++) {
    const a = rootArcs[i];
    const fi = forcedRoots.indexOf(a);
    const Mrest = fi >= 0 ? masterTables(S, forcedRoots, Ffree, fi).M : full;
    for (let q = 1; q <= Q; q++) {
      if (!ok[a * W + q]) continue;
      let best = Infinity;
      for (let b = 0; b <= B - 1; b++) if (Mrest[b][n - q] < best) best = Mrest[b][n - q];
      Out[a * W + q] = best;
    }
  }
  const T = Q - 1;
  for (let Qp = Q; Qp >= 2; Qp--) {
    for (let ap = 0; ap < nA; ap++) {
      const o = Out[ap * W + Qp]; if (o === Infinity) continue;
      const p = arcTail[ap];
      const top = o + arcLen[ap] * price[Qp] - lam[p];
      const ch = childArcs[ap]; const m = ch.length;
      // prefix / suffix knapsacks (totals up to Qp-1)
      const tt = Qp - 1;
      const pre = [new Float64Array(tt + 1).fill(Infinity)]; pre[0][0] = 0;
      for (let ci = 0; ci < m; ci++) {
        const prev = pre[ci], c = ch[ci], mand = isMand(c), cur = new Float64Array(tt + 1);
        for (let t = 0; t <= tt; t++) { let best = mand ? Infinity : prev[t]; for (let q = 1; q <= t; q++) { const v = prev[t - q] + A[c * W + q]; if (v < best) best = v; } cur[t] = best; }
        pre.push(cur);
      }
      const suf = new Array(m + 1); suf[m] = new Float64Array(tt + 1).fill(Infinity); suf[m][0] = 0;
      for (let ci = m - 1; ci >= 0; ci--) {
        const prev = suf[ci + 1], c = ch[ci], mand = isMand(c), cur = new Float64Array(tt + 1);
        for (let t = 0; t <= tt; t++) { let best = mand ? Infinity : prev[t]; for (let q = 1; q <= t; q++) { const v = prev[t - q] + A[c * W + q]; if (v < best) best = v; } cur[t] = best; }
        suf[ci] = cur;
      }
      for (let ci = 0; ci < m; ci++) {
        const c = ch[ci];
        for (let q = 1; q <= tt; q++) {
          if (A[c * W + q] === Infinity) continue;
          const rest = tt - q; let best = Infinity;
          for (let t1 = 0; t1 <= rest; t1++) { const v = pre[ci][t1] + suf[ci + 1][rest - t1]; if (v < best) best = v; }
          if (best === Infinity) continue;
          const v = top + best;
          if (v < Out[c * W + q]) Out[c * W + q] = v;
        }
      }
    }
  }
  const useVal = new Float64Array(nA * W).fill(Infinity);
  for (let a = 0; a < nA; a++) for (let q = 1; q <= Q; q++) { const x = A[a * W + q]; if (x < Infinity && Out[a * W + q] < Infinity) useVal[a * W + q] = x + Out[a * W + q] + lamSum; }
  return useVal;
}

// Subgradient optimisation at a node. Returns {lb, lam, ev}.
function subgradient(S, lam0, ok, forcedArc, UB, target, opts) {
  const n = S.n;
  const lam = Float64Array.from(lam0);
  let best = -Infinity, bestLam = Float64Array.from(lam), bestEv = null;
  let theta = opts.theta0 ?? 0.5, noImp = 0;
  const maxIt = opts.maxIt ?? 60;
  for (let it = 0; it < maxIt; it++) {
    const ev = evaluate(S, lam, ok, forcedArc, true);
    if (ev.value === Infinity) return { lb: Infinity, lam: bestLam, ev: null };
    if (ev.value > best + 1e-7) { best = ev.value; bestLam = Float64Array.from(lam); bestEv = ev; noImp = 0; }
    else if (++noImp >= (opts.patience ?? 8)) { theta *= 0.6; noImp = 0; }
    if (best > target) break;
    let norm = 0; const g = new Float64Array(n);
    for (let k = 0; k < n; k++) { g[k] = 1 - ev.cnt[k]; norm += g[k] * g[k]; }
    if (norm === 0) break;
    const step = theta * (UB - ev.value) / norm;
    for (let k = 0; k < n; k++) lam[k] += step * g[k];
    if (theta < 1e-4) break;
  }
  return { lb: best, lam: bestLam, ev: bestEv };
}

// Check whether a relaxed solution is an actual feasible layout; return parent array or null.
function solutionAsLayout(S, ev) {
  const { n, R, arcHead } = S;
  if (!ev || !ev.cnt) return null;
  for (let k = 0; k < n; k++) if (ev.cnt[k] !== 1) return null;
  const par = new Array(n).fill(-1);
  for (const o of ev.occ) par[o.node] = arcHead[o.arc];
  return par;
}

module.exports = { buildCore, propagate, evaluate, arcUseValues, subgradient, solutionAsLayout, masterTables };
