'use strict';
// Depth-first branch-and-bound with Lagrangian bounds (see bnb_core.js).
// Usage: node bnb.js <scenario> <UB> [maxNodes] [timeLimitSec]
const C = require('./common.js');
const BC = require('./bnb_core.js');

function layoutCost(inst, par) {
  // exact feasibility + cost of a parent array (own check: tree, capacity, crossing, feeders)
  const { n, R, Q } = inst;
  const load = new Array(n).fill(1);
  for (let i = 0; i < n; i++) { let v = par[i], g = 0; while (v !== R) { if (v < 0 || ++g > n) return null; load[v]++; v = par[v]; } }
  let cost = 0, nf = 0; const used = [];
  for (let i = 0; i < n; i++) {
    const e = inst.eid[i * (n + 1) + par[i]]; if (e < 0) return null;
    if (load[i] > Q) return null;
    cost += inst.edges[e].len * inst.priceOf[load[i]]; if (par[i] === R) nf++; used.push(e);
  }
  if (nf > inst.B) return null;
  const set = new Set(used);
  for (const e of used) for (const f of inst.cross[e]) if (set.has(f)) return null;
  return cost;
}

function runBnB(scn, UB0, opts = {}) {
  const inst = C.buildInstance(scn);
  const S = BC.buildCore(inst);
  const { n, nA, W, Q } = S;
  let UB = UB0, bestPar = opts.bestPar || null;
  const ok0 = new Uint8Array(nA * W);
  for (let a = 0; a < nA; a++) for (let q = 1; q <= Q; q++) ok0[a * W + q] = 1;
  const log = opts.log || (() => {});
  const t0 = Date.now();
  // root
  let forced = BC.propagate(S, ok0);
  let lam = new Float64Array(n).fill(UB / n);
  let rootLB = -Infinity;
  if (opts.lam0) lam = Float64Array.from(opts.lam0);
  let sg = BC.subgradient(S, lam, ok0, forced, UB, UB - 5, { maxIt: opts.rootIt ?? 1500, theta0: 1.0, patience: 40 });
  rootLB = sg.lb; lam = sg.lam;
  log(`root LB ${sg.lb.toFixed(1)} (${Date.now() - t0} ms)`);
  // root elimination rounds
  for (let round = 0; round < (opts.rootRounds ?? 5); round++) {
    const use = BC.arcUseValues(S, lam, ok0, forced, sg.ev);
    let killed = 0;
    for (let i = 0; i < use.length; i++) if (ok0[i] && use[i] > UB - 5) { ok0[i] = 0; killed++; }
    forced = BC.propagate(S, ok0);
    if (!forced) { log('root infeasible after elimination => UB optimal'); return { UB, LB: UB, nodes: 0, bestPar, rootLB, proven: true }; }
    sg = BC.subgradient(S, lam, ok0, forced, UB, UB - 5, { maxIt: opts.rootIt2 ?? 300, theta0: 0.3, patience: 20 });
    lam = sg.lam;
    log(`root round ${round}: killed ${killed} (arc,load) pairs, LB ${sg.lb.toFixed(1)}`);
    if (sg.lb > UB - 5) return { UB, LB: UB, nodes: 1, bestPar, rootLB: sg.lb, proven: true };
    if (killed === 0) break;
  }
  const rootLB2 = sg.lb;
  // DFS
  const stack = [{ ok: ok0, lam, lb: sg.lb, depth: 0 }];
  let nodes = 0, pruned = 0;
  const maxNodes = opts.maxNodes ?? Infinity, tLimit = (opts.timeLimit ?? Infinity) * 1000;
  let aborted = false;
  while (stack.length) {
    if (nodes >= maxNodes || Date.now() - t0 > tLimit) { aborted = true; break; }
    const node = stack.pop();
    if (node.lb > UB - 5) { pruned++; continue; }
    nodes++;
    const ok = node.ok;
    let fa = BC.propagate(S, ok);
    if (!fa) { pruned++; continue; }
    let s = BC.subgradient(S, node.lam, ok, fa, UB, UB - 5, { maxIt: opts.nodeIt ?? 40, theta0: opts.nodeTheta ?? 0.2, patience: 6 });
    if (s.lb > UB - 5 || !s.ev) { pruned++; continue; }
    // relaxed solution feasible?
    const cand = BC.solutionAsLayout(S, s.ev);
    if (cand) { const c = layoutCost(inst, cand); if (c !== null && c < UB) { UB = c; bestPar = cand; log(`*** improved UB ${UB} at node ${nodes}`); } }
    // elimination
    const use = BC.arcUseValues(S, s.lam, ok, fa, s.ev);
    let killed = 0;
    for (let i = 0; i < use.length; i++) if (ok[i] && use[i] > UB - 5) { ok[i] = 0; killed++; }
    if (killed) { fa = BC.propagate(S, ok); if (!fa) { pruned++; continue; } }
    // branching turbine: fewest allowed out-arcs (>=2)
    let bk = -1, bcount = Infinity, bscore = -Infinity;
    for (let k = 0; k < n; k++) {
      if (fa[k] >= 0) continue;
      let cnt = 0, vals = [];
      for (const a of S.outArcs[k]) { let m = Infinity; for (let q = 1; q <= Q; q++) if (ok[a * W + q] && use[a * W + q] < m) m = use[a * W + q]; if (m < Infinity) { cnt++; vals.push(m); } }
      if (cnt < 2) continue;
      vals.sort((x, y) => x - y);
      const score = vals[1];
      if (cnt < bcount || (cnt === bcount && score > bscore)) { bk = k; bcount = cnt; bscore = score; }
    }
    if (bk < 0) {
      // all turbines forced => complete layout
      const par = new Array(n); for (let k = 0; k < n; k++) par[k] = S.arcHead[fa[k]];
      const c = layoutCost(inst, par);
      if (c !== null && c < UB) { UB = c; bestPar = par; log(`*** improved UB ${UB} (leaf) at node ${nodes}`); }
      continue;
    }
    const children = [];
    for (const a of S.outArcs[bk]) {
      let m = Infinity; for (let q = 1; q <= Q; q++) if (ok[a * W + q] && use[a * W + q] < m) m = use[a * W + q];
      if (m === Infinity || m > UB - 5) continue;
      const cok = Uint8Array.from(ok);
      for (const b of S.outArcs[bk]) if (b !== a) for (let q = 1; q <= Q; q++) cok[b * W + q] = 0;
      children.push({ ok: cok, lam: s.lam, lb: Math.max(s.lb, m), depth: node.depth + 1 });
    }
    children.sort((x, y) => y.lb - x.lb);
    for (const ch of children) stack.push(ch);
    if (opts.progress && nodes % opts.progress === 0) {
      let minOpen = Infinity; for (const x of stack) if (x.lb < minOpen) minOpen = x.lb;
      log(`nodes ${nodes} stack ${stack.length} depth ${node.depth} UB ${UB} minOpenLB ${minOpen.toFixed(1)} t ${((Date.now() - t0) / 1000).toFixed(0)}s`);
    }
  }
  let LB = UB;
  if (aborted) { for (const x of stack) LB = Math.min(LB, x.lb); }
  return { UB, LB, nodes, pruned, bestPar, rootLB, rootLB2, proven: !aborted, time: Date.now() - t0, open: aborted ? stack : [] };
}

module.exports = { runBnB, layoutCost };

if (require.main === module) {
  const [scn, UBs, maxNodesS, tlS] = process.argv.slice(2);
  const r = runBnB(scn, +UBs, { maxNodes: maxNodesS ? +maxNodesS : Infinity, timeLimit: tlS ? +tlS : Infinity, progress: 200, log: (m) => console.log(m) });
  console.log(JSON.stringify({ scn, UB: r.UB, LB: r.LB, proven: r.proven, nodes: r.nodes, rootLB: r.rootLB, rootLB2: r.rootLB2, time: r.time, bestPar: r.bestPar }));
}
