'use strict';
// Validation of the branch-and-bound (and the Lagrangian bound) against
// exhaustive enumeration on small random sub-instances built from the real
// turbine coordinates.  Usage: node tests/validate_bnb.js [nTests] [seed]
const C = require('../common.js');
const BNB = require('../bnb.js');
const SA = require('../sa.js');

function bruteForce(inst) {
  const { n, R, Q, B } = inst;
  const opts = []; for (let i = 0; i < n; i++) opts.push(inst.adj[i].slice());
  const par = new Int32Array(n).fill(-1);
  let best = Infinity, bestPar = null;
  const usedEdges = [];
  function rec(i) {
    if (i === n) {
      // check tree + loads
      const load = new Int32Array(n).fill(1);
      for (let k = 0; k < n; k++) { let v = par[k], g = 0; while (v !== R) { if (++g > n) return; load[v]++; v = par[v]; } }
      let cost = 0, nf = 0;
      for (let k = 0; k < n; k++) { if (load[k] > Q) return; const e = inst.eid[k * (n + 1) + par[k]]; cost += inst.edges[e].len * inst.priceOf[load[k]]; if (par[k] === R) nf++; }
      if (nf > B) return;
      if (cost < best) { best = cost; bestPar = Array.from(par); }
      return;
    }
    for (const p of opts[i]) {
      const e = inst.eid[i * (n + 1) + p];
      // crossing with already chosen edges
      let bad = false;
      for (const f of usedEdges) { if (inst.cross[e].includes(f)) { bad = true; break; } }
      if (bad) continue;
      // early cycle check: walk up from p among assigned
      let v = p, g = 0, cyc = false;
      while (v !== R && v < i && par[v] >= 0) { if (v === i) { cyc = true; break; } v = par[v]; if (++g > n) { cyc = true; break; } }
      if (v === i) cyc = true;
      if (cyc) continue;
      par[i] = p; usedEdges.push(e);
      rec(i + 1);
      usedEdges.pop(); par[i] = -1;
    }
  }
  rec(0);
  return { best, bestPar };
}

function makeRandomInstance(rnd, idx) {
  const m = 7 + Math.floor(rnd() * 4); // 7..10 turbines
  const center = C.TURBINES[Math.floor(rnd() * 64)];
  const sorted = C.TURBINES.map((p, i) => [Math.hypot(p[0] - center[0], p[1] - center[1]), i]).sort((a, b) => a[0] - b[0]);
  const pick = sorted.slice(0, m).map(x => C.TURBINES[x[1]]);
  const rootChoices = [C.PLATFORMS.P, C.PLATFORMS.A, [center[0] + 350, center[1] - 420], [center[0] - 900, center[1] + 100]];
  const root = rootChoices[Math.floor(rnd() * rootChoices.length)];
  const capSets = [[{ name: 'C1', cap: 2, price: 100 }, { name: 'C2', cap: 4, price: 160 }, { name: 'C3', cap: 6, price: 245 }],
                   [{ name: 'C2', cap: 3, price: 160 }, { name: 'C3', cap: 5, price: 245 }],
                   [{ name: 'C1', cap: 1, price: 100 }, { name: 'C2', cap: 3, price: 160 }, { name: 'C3', cap: 7, price: 245 }]];
  const types = capSets[Math.floor(rnd() * capSets.length)];
  const Q = Math.max(...types.map(t => t.cap));
  const B = Math.max(Math.ceil(m / Q), 1 + Math.floor(rnd() * 3));
  const scn = { platform: 'R', types: types.map(t => t.name), B };
  return C.buildInstanceFrom('T' + idx, scn, pick, root, types);
}

const nTests = +(process.argv[2] || 30), seed = +(process.argv[3] || 7);
const rnd = SA.mulberry32(seed);
let fails = 0, done = 0;
for (let t = 0; t < nTests; t++) {
  const inst = makeRandomInstance(rnd, t);
  // candidate graph must allow a solution
  const bf = bruteForce(inst);
  if (bf.best === Infinity) { continue; }
  done++;
  // (1) B&B started with UB = opt + 5 must find a solution of cost opt
  const r1 = BNB.runBnB('T' + t, bf.best + 5, { inst, rootIt: 400, rootRounds: 3 });
  // (2) B&B started with UB = opt must prove (no solution < opt)
  const r2 = BNB.runBnB('T' + t, bf.best, { inst, rootIt: 400, rootRounds: 3 });
  // (3) B&B started with a loose UB (opt * 1.3) must reach opt
  const r3 = BNB.runBnB('T' + t, Math.round(bf.best * 1.3 / 5) * 5, { inst, rootIt: 400, rootRounds: 3 });
  const ok1 = r1.UB === bf.best, ok2 = r2.UB === bf.best && r2.proven, ok3 = r3.UB === bf.best;
  const okLB = r2.rootLB <= bf.best + 1e-6;
  if (!(ok1 && ok2 && ok3 && okLB)) fails++;
  console.log(`test ${t}: n=${inst.n} Q=${inst.Q} B=${inst.B} brute=${bf.best} | bnb(UB=opt+5)->${r1.UB} bnb(UB=opt) proven=${r2.proven} rootLB=${r2.rootLB.toFixed(1)} | bnb(loose)->${r3.UB} ${ok1 && ok2 && ok3 && okLB ? 'OK' : 'FAIL'}`);
}
console.log(`validated ${done} instances, failures: ${fails}`);
