console.log('n', inst.n, 'Q', inst.Q, 'B', inst.B, 'opt', bf.best, 'par', bf.bestPar.join(','));
const S = BC.buildCore(inst);
const { n, nA, W, Q } = S;
// optimal solution's (arc, load) pairs
const ev0 = C.evaluate(inst, bf.bestPar);
const optPairs = bf.bestPar.map((p, k) => [S.arcOf[k * S.N1 + p], ev0.load[k]]);
console.log('opt pairs', optPairs.map(([a, q]) => `${S.arcTail[a]}>${S.arcHead[a]}@${q}`).join(' '));
const UB = bf.best + 5, TGT = UB - 4;
const ok = new Uint8Array(nA * W); for (let a = 0; a < nA; a++) for (let q = 1; q <= Q; q++) ok[a * W + q] = 1;
const consistent = (okm) => optPairs.every(([a, q]) => okm[a * W + q]);
let forced = BC.propagate(S, ok);
console.log('after propagate root consistent?', consistent(ok), forced ? 'feasible' : 'INFEASIBLE');
let lam = new Float64Array(n).fill(UB / n);
let sg = BC.subgradient(S, lam, ok, forced, UB, TGT, { maxIt: 400, theta0: 1.0, patience: 40 });
console.log('root LB', sg.lb);
// check useVal for opt pairs
const use = BC.arcUseValues(S, sg.lam, ok, forced, sg.ev);
// The relaxed value of the optimal solution itself with these multipliers:
let lamSum = 0; for (let k = 0; k < n; k++) lamSum += sg.lam[k];
// Lagrangian value of opt solution = cost - sum(lam) + sum(lam) = cost (cnt=1)
for (const [a, q] of optPairs) {
  const u = use[a * W + q];
  console.log(`pair ${S.arcTail[a]}>${S.arcHead[a]}@${q}: useVal ${u.toFixed(2)} ${u > bf.best + 1e-6 ? '<-- OVERESTIMATE (opt cost ' + bf.best + ')' : ''}`);
}
