const lab = v => C.label(inst, v);
const treeStr = (r, f) => {
  const occs = r.occ.map((o, i) => [o, i]).filter(([o]) => o.feeder === f);
  const root = occs.find(([o]) => o.par === -1)[0];
  const ch = new Map(); occs.forEach(([o, i]) => { if (o.par >= 0) { if (!ch.has(o.par)) ch.set(o.par, []); ch.get(o.par).push(i); } });
  const rec = (i) => { const o = r.occ[i]; const c = ch.get(i) || []; return lab(o.node) + (c.length ? '(' + c.map(rec).join(',') + ')' : ''); };
  return 'load ' + root.load + ': ' + rec(r.occ.indexOf(root));
};
const seen = new Map();
let theta = 0.01;
for (let it = 0; it < 400; it++) {
  const r = LG.evaluate(S, lam, arcPen, allowed, true);
  const nf = new Set(r.occ.map(o => o.feeder)).size;
