// Knuth tree-size estimate for the B&B (random dives)
const C = require('/app/optimizer/common.js');
const BC = require('/app/optimizer/bnb_core.js');
const SA = require('/app/optimizer/sa.js');
const [scn, UBs, probesS, seedS] = process.argv.slice(2);
const UB = +UBs, probes = +(probesS || 30), rnd = SA.mulberry32(+(seedS || 1));
const inst = C.buildInstance(scn); const S = BC.buildCore(inst); const { n, nA, W, Q } = S;
const TGT = UB - 4;
const ok0 = new Uint8Array(nA * W); for (let a = 0; a < nA; a++) for (let q = 1; q <= Q; q++) ok0[a * W + q] = 1;
let fa = BC.propagate(S, ok0);
let sg = BC.subgradient(S, new Float64Array(n).fill(UB / n), ok0, fa, UB, TGT, { maxIt: 1500, theta0: 1.0, patience: 40 });
for (let r = 0; r < 4; r++) { const use = BC.arcUseValues(S, sg.lam, ok0, fa); let k = 0; for (let i = 0; i < use.length; i++) if (ok0[i] && use[i] > TGT) { ok0[i] = 0; k++; } fa = BC.propagate(S, ok0); sg = BC.subgradient(S, sg.lam, ok0, fa, UB, TGT, { maxIt: 300, theta0: 0.3, patience: 20 }); if (!k) break; }
console.log('root LB', sg.lb.toFixed(1));
const rootLam = sg.lam;
const ests = [];
for (let p = 0; p < probes; p++) {
  let ok = Uint8Array.from(ok0), lam = rootLam, est = 1, mult = 1, depth = 0;
  while (true) {
    const f = BC.propagate(S, ok); if (!f) break;
    const s = BC.subgradient(S, lam, ok, f, UB, TGT, { maxIt: 40, theta0: 0.2, patience: 6 });
    if (s.lb > TGT || !s.ev) break;
    const use = BC.arcUseValues(S, s.lam, ok, f);
    for (let i = 0; i < use.length; i++) if (ok[i] && use[i] > TGT) ok[i] = 0;
    const f2 = BC.propagate(S, ok); if (!f2) break;
    let bk = -1, bcount = Infinity, bscore = -Infinity, bchildren = null;
    for (let k = 0; k < n; k++) {
      if (f2[k] >= 0) continue;
      const vals = [];
      for (const a of S.outArcs[k]) { let m = Infinity; for (let q = 1; q <= Q; q++) if (ok[a * W + q] && use[a * W + q] < m) m = use[a * W + q]; if (m < Infinity && m <= TGT) vals.push([m, a]); }
      if (vals.length < 2) continue;
      vals.sort((x, y) => x[0] - y[0]);
      if (vals.length < bcount || (vals.length === bcount && vals[1][0] > bscore)) { bk = k; bcount = vals.length; bscore = vals[1][0]; bchildren = vals; }
    }
    if (bk < 0) break;
    mult *= bchildren.length; est += mult; depth++;
    const pick = bchildren[Math.floor(rnd() * bchildren.length)][1];
    for (const b of S.outArcs[bk]) if (b !== pick) for (let q = 1; q <= Q; q++) ok[b * W + q] = 0;
    lam = s.lam;
  }
  ests.push(est);
  console.log(`probe ${p}: depth ${depth} estimate ${est.toExponential(2)}`);
}
ests.sort((a, b) => a - b);
const mean = ests.reduce((a, b) => a + b, 0) / ests.length;
console.log('mean estimate', mean.toExponential(2), 'median', ests[Math.floor(ests.length / 2)].toExponential(2));
EOF
