'use strict';
// Parallel branch-and-bound (master/worker, Node.js child_process IPC).
// Usage: node pbnb.js <scenario> <UB> [workers] [timeLimitSec] [outJson]
// The master keeps a best-first queue of open subproblems; each worker runs a
// budgeted depth-first search from a subproblem and returns the unexplored
// remainder.  The global lower bound is the minimum bound over all open
// subproblems; the search proves optimality of the incumbent when nothing is
// left open.
const { fork } = require('child_process');
const fs = require('fs');
const os = require('os');
const C = require('./common.js');
const BC = require('./bnb_core.js');

const GAPTOL = 4.0;   // prune iff LB > UB - 4 (all costs are multiples of 5)

function layoutCost(inst, par) {
  const { n, R, Q } = inst;
  const load = new Array(n).fill(1);
  for (let i = 0; i < n; i++) { let v = par[i], g = 0; while (v !== R) { if (v < 0 || ++g > n) return null; load[v]++; v = par[v]; } }
