const enc = (u8) => Buffer.from(u8).toString('base64');
const dec = (s) => new Uint8Array(Buffer.from(s, 'base64'));

// Process one node: bound, fix, branch. Returns {status, children, cand}
function processNode(S, inst, node, UB, opts) {
  const { n, W, Q } = S;
