  const finish = (reason) => {
    if (finished) return; finished = true;
    const LB = queue.length || busy.size ? globalLB() : UB;
    const res = { scenario: scn, UB, LB: Math.min(LB, UB), proven: !queue.length && !busy.size, rootLB, nodes: totalNodes, seconds: (Date.now() - t0) / 1000, reason, bestPar, openNodes: queue.length + busy.size };
    log(`finished (${reason}): UB ${UB} LB ${res.LB.toFixed(1)} proven ${res.proven} nodes ${totalNodes}`);
    if (outFile) fs.writeFileSync(outFile, JSON.stringify(res, null, 1));
