// Simple greedy baseline ("capacitated nearest-attachment", Prim-like):
// start with only the platform connected; repeatedly add the single cheapest
// feasible cable that connects an unconnected turbine to the connected
// network (another turbine or the platform), where "cheapest" is the
// increase in total layout cost (the new cable at load 1 plus any cable
// upgrades on the path to the platform).  A candidate cable must respect the
// 1300 m limit, the capacity of the largest available type on the whole path,
// the feeder-bay limit and must not cross any cable already laid.
// No look-ahead, no improvement phase.
const C = require('./common.js');

function greedyLayout(inst) {
  const { n, R, Q, B } = inst;
  const N1 = n + 1;
  const par = new Array(n).fill(-1), load = new Array(n).fill(0);
  const connected = new Uint8Array(N1); connected[R] = 1;
  const used = new Set();
  let nf = 0, cost = 0;
  const lenOf = (a, b) => inst.edges[inst.eid[a * N1 + b]].len;
  for (let step = 0; step < n; step++) {
    let best = null;
    for (let u = 0; u < n; u++) {
      if (connected[u]) continue;
      for (const v of inst.adj[u]) {
        if (!connected[v]) continue;
        if (v === R && nf >= B) continue;
        const e = inst.eid[u * N1 + v];
        if (inst.cross[e].some(f => used.has(f))) continue;
        // capacity and upgrade cost along the path v -> R
        let d = inst.edges[e].len * inst.priceOf[1], w = v, okCap = true;
        while (w !== R) { if (load[w] + 1 > Q) { okCap = false; break; } const L = lenOf(w, par[w]); d += L * (inst.priceOf[load[w] + 1] - inst.priceOf[load[w]]); w = par[w]; }
        if (!okCap) continue;
        if (!best || d < best.d || (d === best.d && (u < best.u || (u === best.u && v < best.v)))) best = { u, v, e, d };
      }
    }
