    for (const w of workers) {
      w.removeAllListeners('message');
      w.on('message', (r) => { results[r.id] = r; done++; if (done === jobs.length) resolve(results); else give(w); });
      give(w);
    }
  });
  for (const scn of o.scenarios) {
    const inst = C.buildInstance(scn);
    const t0 = Date.now();
    let pool = []; // {cost, par}
    // cross-seeding from the store (any scenario with the same platform)
    const store = loadStore(o.store);
    for (const [s2, sol] of Object.entries(store)) {
      if (C.SCENARIOS[s2].platform !== inst.scn.platform) continue;
      const c = feasibleFor(inst, sol.par); if (c !== null) pool.push({ cost: c, par: sol.par, from: s2 });
    }
    for (let round = 0; round < o.rounds; round++) {
      const jobs = [];
      for (let r = 0; r < o.runs; r++) {
        const seed = o.seed * 1000003 + round * 10007 + r * 101 + scn.charCodeAt(1);
        if (round === 0 || !pool.length) jobs.push({ scn, seed, iters: o.iters, T0: 30000, T1: 30, startPar: null });
        else {
          pool.sort((a, b) => a.cost - b.cost);
          const src = pool[r % Math.min(4, pool.length)];
          jobs.push({ scn, seed, iters: o.iters, T0: [3000, 8000, 15000][r % 3], T1: 20, startPar: src.par });
        }
      }
      const res = await runJobs(jobs);
      for (const r of res) if (r && r.par) pool.push({ cost: r.cost, par: r.par });
      // de-duplicate pool by cost+par
      const seen = new Set(); pool = pool.filter(p => { const k = p.par.join(','); if (seen.has(k)) return false; seen.add(k); return true; });
      pool.sort((a, b) => a.cost - b.cost);
      console.log(`${scn} round ${round}: best ${pool[0].cost} (top: ${pool.slice(0, 6).map(p => p.cost).join(' ')}) [${((Date.now() - t0) / 1000).toFixed(0)}s]`);
    }
    const best = pool[0];
    const saved = saveIfBetter(o.store, scn, inst, best.par, 'simulated annealing portfolio');
    console.log(`${scn}: best heuristic cost ${best.cost}${saved ? ' (stored)' : ' (store already had an equal or better layout)'}`);
  }
  for (const w of workers) w.kill();
}

if (process.argv[2] === '--worker') workerMain(); else if (require.main === module) masterMain();
module.exports = { feasibleFor, saveIfBetter, loadStore };
