'use strict';
// Derive three deliberately broken layouts from the S1 layout (test inputs
// for the independent checker).  Each one violates exactly one packet rule;
// all other cables keep correct loads/types so only the target rule fails.
//   S1_broken_crossing.csv : one leaf turbine re-cabled so that two cables cross
//   S1_broken_capacity.csv : one cable labelled with a type whose capacity < load
//   S1_broken_length.csv   : one leaf turbine re-cabled to a turbine > 1300 m away
// Usage: node make_broken.js [S1 layout store json] [outDir]
const fs = require('fs');
const path = require('path');
const C = require('./common.js');

const store = process.argv[2] || path.join(__dirname, '..', 'results', 'solutions', 'S1.json');
const outDir = process.argv[3] || path.join(__dirname, '..', 'layouts', 'broken');
fs.mkdirSync(outDir, { recursive: true });
const inst = C.buildInstance('S1');
const { n, R, pts } = inst;
const base = JSON.parse(fs.readFileSync(store, 'utf8')).par;

function loads(par) { const l = new Array(n).fill(1); for (let i = 0; i < n; i++) { let v = par[i]; while (v !== R) { l[v]++; v = par[v]; } } return l; }
function typeFor(q) { return inst.typeOf[q]; }
function write(name, par, typeOverride, comments) {
  const L = loads(par);
  const lines = ['# ARRAY-11 inter-array cable layout -- DELIBERATELY BROKEN test case'];
  for (const c of comments) lines.push('# ' + c);
  const rows = []; let total = 0, nf = 0;
  for (let i = 0; i < n; i++) {
    const t = (typeOverride && typeOverride[i]) || typeFor(L[i]);
    const price = C.CABLES.find(c => c.name === t).price;
    const len = C.roundedLength(pts[i], pts[par[i]]);
    total += len * price; if (par[i] === R) nf++;
    rows.push(`${C.label(inst, i)},${C.label(inst, par[i])},${t},${L[i]},${len},${len * price}`);
  }
  lines.push('scenario,S1', 'platform,P', 'feeder_bays,6', 'cable_types,C1;C2;C3', `total_cost,${total}`, `feeders_used,${nf}`, 'from,to,type,load,length_m,cost', ...rows);
  fs.writeFileSync(path.join(outDir, name), lines.join('\n') + '\n');
  console.log('wrote', path.join(outDir, name), 'cost', total);
}
function inSubtree(par, u, v) { let w = v; while (w !== R) { if (w === u) return true; w = par[w]; } return false; }
function crossingsOf(par, i) { // list of cables crossing cable i -> par[i]
  const out = [];
  for (let j = 0; j < n; j++) if (j !== i && C.cablesCross(pts, i, par[i], j, par[j])) out.push(j);
  return out;
}
const L0 = loads(base);
const leaves = [...Array(n).keys()].filter(i => L0[i] === 1);

// (1) crossing: leaf u re-cabled to turbine v (<=1300 m) producing exactly one crossing
let done1 = false;
for (const u of leaves) {
  if (done1) break;
  for (let v = 0; v < n && !done1; v++) {
    if (v === u || v === base[u] || inSubtree(base, u, v)) continue;
    if (C.roundedLength(pts[u], pts[v]) > 1300) continue;
    const par = base.slice(); par[u] = v;
    const L = loads(par); if (Math.max(...L) > 14) continue;
    const cr = crossingsOf(par, u);
    if (cr.length !== 1) continue;
    // ensure no other crossings exist
    let other = 0; for (let i = 0; i < n; i++) if (i !== u) for (let j = i + 1; j < n; j++) if (j !== u && C.cablesCross(pts, i, par[i], j, par[j])) other++;
    if (other) continue;
    write('S1_broken_crossing.csv', par, null, [`derived from the S1 layout: ${C.label(inst, u)} re-cabled from ${C.label(inst, base[u])} to ${C.label(inst, v)};`, `its cable now crosses ${C.label(inst, cr[0])}-${C.label(inst, par[cr[0]])}. Expected checker verdict: REJECTED, rule no-crossing.`]);
    done1 = true;
  }
}
// (2) capacity: a C2 cable (load 5..8) relabelled C1 (capacity 4)
{
  const i = [...Array(n).keys()].find(k => L0[k] >= 5 && L0[k] <= 8);
  const ov = {}; ov[i] = 'C1';
  write('S1_broken_capacity.csv', base, ov, [`derived from the S1 layout: cable ${C.label(inst, i)}-${C.label(inst, base[i])} carries ${L0[i]} turbines but is labelled C1 (capacity 4).`, 'Expected checker verdict: REJECTED, rule capacity.']);
}
// (3) length: leaf u re-cabled to a turbine v with 1300 < length, no crossing
let done3 = false;
const cands = [];
for (const u of leaves) for (let v = 0; v < n; v++) {
  if (v === u || inSubtree(base, u, v)) continue;
  const len = C.roundedLength(pts[u], pts[v]);
  if (len <= 1300) continue;
  cands.push([len, u, v]);
}
cands.sort((a, b) => a[0] - b[0]);
for (const [len, u, v] of cands) {
  const par = base.slice(); par[u] = v;
  const L = loads(par); if (Math.max(...L) > 14) continue;
  if (crossingsOf(par, u).length) continue;
  write('S1_broken_length.csv', par, null, [`derived from the S1 layout: ${C.label(inst, u)} re-cabled from ${C.label(inst, base[u])} to ${C.label(inst, v)}, a ${len} m turbine-to-turbine cable.`, 'Expected checker verdict: REJECTED, rule length-limit.']);
  done3 = true; break;
}
if (!done1 || !done3) console.log('WARNING: could not build all broken layouts', done1, done3);
