'use strict';
// Larger validation: 10-12 turbines, real catalogue (C1 4/100, C2 8/160, C3 14/245)
// or the S3 catalogue, B = 1..2, roots P / A / nearby points.  Brute force vs B&B.
const C = require('../common.js');
const BNB = require('../bnb.js');
const SA = require('../sa.js');
const V = require('./validate_bnb_lib.js');
const nTests = +(process.argv[2] || 10), seed = +(process.argv[3] || 3);
const rnd = SA.mulberry32(seed);
let fails = 0, done = 0;
for (let t = 0; t < nTests; t++) {
  const m = 10 + Math.floor(rnd() * 3);
  const center = C.TURBINES[Math.floor(rnd() * 64)];
  const sorted = C.TURBINES.map((p, i) => [Math.hypot(p[0] - center[0], p[1] - center[1]), i]).sort((a, b) => a[0] - b[0]);
  const pick = sorted.slice(0, m).map(x => C.TURBINES[x[1]]);
  const roots = [C.PLATFORMS.P, C.PLATFORMS.A, [center[0] + 250, center[1] + 330]];
  const root = roots[Math.floor(rnd() * roots.length)];
  const types = rnd() < 0.7 ? C.CABLES : C.CABLES.filter(c => c.name !== 'C1');
  const B = 1 + Math.floor(rnd() * 2);
  const inst = C.buildInstanceFrom('X' + t, { platform: 'R', types: types.map(c => c.name), B }, pick, root, types);
  const t0 = Date.now();
  const bf = V.bruteForce(inst);
  const tb = Date.now() - t0;
  if (bf.best === Infinity) { console.log(`test ${t}: infeasible instance, skipped`); continue; }
  done++;
  const r1 = BNB.runBnB('X' + t, bf.best + 5, { inst, rootIt: 600, rootRounds: 4 });
  const r3 = BNB.runBnB('X' + t, Math.round(bf.best * 1.2 / 5) * 5, { inst, rootIt: 600, rootRounds: 4 });
  const ok = r1.UB === bf.best && r3.UB === bf.best && r1.proven && r3.proven;
  if (!ok) fails++;
  console.log(`test ${t}: n=${m} B=${B} types=${types.map(c => c.name).join('/')} brute=${bf.best} (${tb} ms) | bnb(opt+5)->${r1.UB} nodes ${r1.nodes} | bnb(+20%)->${r3.UB} nodes ${r3.nodes} ${ok ? 'OK' : 'FAIL'}`);
}
console.log(`validated ${done} instances, failures: ${fails}`);
