  const bnb = fs.existsSync(bnbFile) ? JSON.parse(fs.readFileSync(bnbFile, 'utf8')) : null;
  const inst = C.buildInstance(s);
  const ev = C.evaluate(inst, sol.par);
  if (ev.cost !== sol.cost) throw new Error('store inconsistent for ' + s);
  let LB = null, how = 'none', rootLB = null, nodes = null, secs = null;
  if (bnb) {
    rootLB = Math.ceil(bnb.rootLB / 5) * 5;   // costs are multiples of 5
    nodes = bnb.nodes; secs = bnb.seconds;
    if (bnb.proven && bnb.UB >= ev.cost) { LB = ev.cost; how = 'complete branch-and-bound (Lagrangian bounds)'; }
    else { LB = Math.ceil(Math.min(bnb.LB, ev.cost) / 5) * 5; how = 'branch-and-bound (incomplete): min open-node bound'; }
  }
  rows.push({ s, platform: inst.scn.platform, B: inst.B, types: inst.scn.types.join('/'), cost: ev.cost, feeders: ev.feeders,
    LB, gap: LB === null ? null : ev.cost - LB, gapPct: LB === null ? null : (100 * (ev.cost - LB) / ev.cost), how, rootLB, rootGap: rootLB === null ? null : ev.cost - rootLB, nodes, secs,
    status: LB === ev.cost ? 'proven optimal' : 'not proven' });
}
const md = [];
md.push('| Scenario | Platform | B | Cable types | Layout cost | Feeders used | Lower bound | Gap | Status | Root Lagrangian bound (gap) | B&B nodes | B&B time (s) |');
md.push('|---|---|---|---|---:|---:|---:|---:|---|---:|---:|---:|');
for (const r of rows) md.push(`| ${r.s} | ${r.platform} | ${r.B} | ${r.types} | ${r.cost} | ${r.feeders} | ${r.LB} | ${r.gap} (${r.gapPct.toFixed(2)}%) | ${r.status} | ${r.rootLB} (${r.rootGap}, ${(100 * r.rootGap / r.cost).toFixed(2)}%) | ${r.nodes} | ${r.secs.toFixed(0)} |`);
const csv = ['scenario,platform,B,cable_types,cost,feeders_used,lower_bound,gap,gap_percent,status,lower_bound_method,root_lagrangian_bound,root_gap,bnb_nodes,bnb_seconds'];
for (const r of rows) csv.push([r.s, r.platform, r.B, r.types, r.cost, r.feeders, r.LB, r.gap, r.gapPct.toFixed(4), r.status, r.how, r.rootLB, r.rootGap, r.nodes, r.secs.toFixed(1)].join(','));
fs.writeFileSync(path.join(res, 'results_table.md'), md.join('\n') + '\n');
fs.writeFileSync(path.join(res, 'results_table.csv'), csv.join('\n') + '\n');
console.log(md.join('\n'));
EOF
