const SA = require('../sa.js');

const { bruteForce, makeRandomInstance } = require('./validate_bnb_lib.js');

const nTests = +(process.argv[2] || 30), seed = +(process.argv[3] || 7);
const rnd = SA.mulberry32(seed);
let fails = 0, done = 0;
